(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  // ── Module 4 helpers: seeded randomness, small shapes ─────────────────────
  function mulberry(seed) {
    var a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gaussSource(rand) {
    return function () {
      var u = 1 - rand(), v = rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
  }
  function box(parent, x, y, w, h, fill, stroke, r) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: r === undefined ? 6 : r, fill: fill, stroke: stroke || "none", "stroke-width": 2 }, parent);
  }
  function setBox(node, x, y, w, h) {
    node.setAttribute("x", x); node.setAttribute("y", y); node.setAttribute("width", Math.max(0, w)); node.setAttribute("height", Math.max(0, h));
  }
  function vis(list, on) {
    list.forEach(function (n) { show(n, on); });
  }

  var EXPLAIN = {"same-mean":{"h":"WHAT YOU ARE LOOKING AT","t":"**A** takes the values 4, 5, 6 with probabilities 0.25, 0.5, 0.25. **B** takes 0, 5, 10 with the same probabilities. Both balance at **5**: their mean is the same."},"different-spread":{"h":"BUT THEY ARE SPREAD DIFFERENTLY","t":"A stays within **1** of the mean. B stretches **5** away on each side. The mean cannot tell them apart, so we need a second number: the **spread**."},"mean":{"h":"START FROM THE MEAN","t":"Focus on A. Its mean is **5**. To measure spread we ask, for each value, **how far it is from this mean**."},"deviations":{"h":"DEVIATIONS FROM THE MEAN","t":"The deviation of a value is its signed distance from the mean: **4 is −1, 5 is 0, 6 is +1**. Averaging these just gives 0, because the minus and plus **cancel**."},"square-deviations":{"h":"SQUARE THE DEVIATIONS","t":"Squaring removes the signs and punishes bigger misses more: **(−1)² = 1, 0² = 0, (+1)² = 1**. Each square is drawn with that area (tiny here)."},"average":{"h":"AVERAGE THE SQUARES","t":"Take the probability-weighted average of the squares: **0.25 × 1 + 0.5 × 0 + 0.25 × 1 = 0.5**. That is the **variance: Var(A) = 0.5**."},"compare-variance":{"h":"COMPARE WITH B","t":"For B the deviations are **−5, 0, +5**, so the squares are **25, 0, 25** (big squares). **Var(B) = 12.5**, which is **25 times larger** than Var(A)."},"ml-connection":{"h":"TAKEAWAY","t":"Variance tells how **uncertain a prediction is** or how much a feature varies. The standard deviation (its square root) is in the original units: about **0.71 for A and 3.54 for B**."}};
  // ── scene ──
  var steps = [
    { id: "same-mean", label: "Two distributions, same mean", caption: "A takes the values 4, 5, 6 with probabilities 0.25, 0.5, 0.25. B takes 0, 5, 10 with the same probabilities. Both balance at 5: their mean (expected value) is 5." },
    { id: "different-spread", label: "But they are spread differently", caption: "A stays within 1 of the mean. B stretches 5 away on each side. The mean cannot tell them apart, so we need a second number: the spread." },
    { id: "mean", label: "Start from the mean", caption: "Focus on A. Its mean is 5. To measure spread we will ask, for each value, how far it is from this mean." },
    { id: "deviations", label: "Deviations from the mean", caption: "The deviation of a value is its distance from the mean with a sign: 4 is −1 away, 5 is 0 away, 6 is +1 away. Averaging these just gives 0, because the minus and plus cancel." },
    { id: "square-deviations", label: "Square the deviations", caption: "Squaring removes the signs and punishes bigger misses more: (−1)² = 1, 0² = 0, (+1)² = 1. Each square is drawn with that area (tiny here)." },
    { id: "average", label: "Average the squares", caption: "Take the probability-weighted average of the squares: 0.25 × 1 + 0.5 × 0 + 0.25 × 1 = 0.5. That is the variance: Var(A) = 0.5." },
    { id: "compare-variance", label: "Compare with B", caption: "For B the deviations are −5, 0, +5, so the squares are 25, 0, 25 (big squares). Var(B) = 0.25 × 25 + 0 + 0.25 × 25 = 12.5, which is 25 times larger than Var(A)." },
    { id: "ml-connection", label: "Why variance matters in ML", caption: "Variance tells how uncertain a prediction is or how much a feature varies. Standard deviation (the square root) is in the original units: about 0.71 for A and 3.54 for B." }
  ];

  var XS = function (v) { return 70 + 50 * v; };
  var yA = 130, yB = 244, HS = 140;

  function chart(parent, base, vals, color, title) {
    var g = el("g", {}, parent);
    el("line", { x1: 40, y1: base, x2: 600, y2: base, class: "axis" }, g);
    [0, 5, 10].forEach(function (v) { txt(g, XS(v), base + 16, "tick", String(v), "middle"); });
    vals.forEach(function (vp) {
      box(g, XS(vp[0]) - 14, base - vp[1] * HS, 28, vp[1] * HS, color, "none", 3);
    });
    txt(g, 20, base - 70, "big", title, "start").setAttribute("font-size", "22");
    var m = el("line", { x1: XS(5), y1: base - 88, x2: XS(5), y2: base, stroke: "#e2b44a", "stroke-width": 2.5, "stroke-dasharray": "6 4" }, g);
    // Probability labels are drawn after the mean line, with a dark outline, so the dashed line never strikes through them.
    vals.forEach(function (vp) {
      var label = txt(g, XS(vp[0]), base - vp[1] * HS - 6, "lbl", String(vp[1]), "middle");
      label.setAttribute("stroke", "#071510");
      label.setAttribute("stroke-width", "4");
      label.setAttribute("paint-order", "stroke");
    });
    txt(g, XS(5) + 8, base - 94, "lbl lbl-y", "mean 5", "start");
    return g;
  }
  var gA = chart(svg, yA, [[4, 0.25], [5, 0.5], [6, 0.25]], "rgba(56,189,248,0.8)", "A");
  var gB = chart(svg, yB, [[0, 0.25], [5, 0.5], [10, 0.25]], "rgba(244,114,182,0.8)", "B");

  var spreadG = el("g", {}, svg);
  var sa = arrow(spreadG, "g", 3); setLine(sa, XS(5) - 6, yA + 36, XS(4) - 14, yA + 36);
  var sb = arrow(spreadG, "g", 3); setLine(sb, XS(5) + 6, yA + 36, XS(6) + 14, yA + 36);
  txt(spreadG, XS(5), yA + 52, "lbl lbl-g", "narrow", "middle");
  var sc = arrow(spreadG, "r", 3); setLine(sc, XS(5) - 6, yB + 36, XS(0), yB + 36);
  var sd = arrow(spreadG, "r", 3); setLine(sd, XS(5) + 6, yB + 36, XS(10), yB + 36);
  txt(spreadG, XS(5), yB + 52, "lbl lbl-r", "wide", "middle");

  function devs(parent, base, pairs, color) {
    var g = el("g", {}, parent);
    pairs.forEach(function (p) {
      var d = p[1];
      if (d !== 0) {
        var a = arrow(g, color, 3);
        setLine(a, XS(5), base + 30, XS(p[0]) + (d > 0 ? -16 : 16), base + 30);
      } else {
        el("circle", { cx: XS(5), cy: base + 30, r: 4, fill: "#c9dccf" }, g);
      }
      txt(g, XS(p[0]), base + 50, "lbl", (d > 0 ? "+" : d < 0 ? "−" : "") + Math.abs(d), "middle");
    });
    return g;
  }
  var devA = devs(svg, yA, [[4, -1], [5, 0], [6, 1]], "y");
  var devB = devs(svg, yB, [[0, -5], [5, 0], [10, 5]], "y");

  function squares(parent, base, pairs, color) {
    var g = el("g", {}, parent);
    pairs.forEach(function (p) {
      var side = Math.abs(p[1]) * 6;
      if (side > 0) box(g, XS(p[0]) - side / 2, base + 56, side, side, color, "none", 1);
      txt(g, XS(p[0]), base + 56 + Math.max(side, 6) + 14, "lbl", String(p[1] * p[1]), "middle");
    });
    return g;
  }
  var sqA = squares(svg, yA, [[4, -1], [5, 0], [6, 1]], "rgba(56,189,248,0.9)");
  var sqB = squares(svg, yB, [[0, -5], [5, 0], [10, 5]], "rgba(244,114,182,0.9)");

  var avgG = el("g", {}, svg);
  card(avgG, 60, 196, 520, 120, "fillG");
  txt(avgG, 320, 224, "lbl lbl-g", "variance = the probability-weighted average of the squares", "middle");
  txt(avgG, 320, 258, "mono", "0.25 × 1  +  0.5 × 0  +  0.25 × 1", "middle");
  txt(avgG, 320, 296, "big", "Var(A) = 0.5", "middle").setAttribute("font-size", "20");

  var cmpG = el("g", {}, svg);
  card(cmpG, 430, 8, 190, 46, "fillA");
  txt(cmpG, 450, 36, "note", "Var(A) =", "start");
  txt(cmpG, 540, 40, "big", "0.5", "start").setAttribute("font-size", "22");
  card(cmpG, 430, 62, 190, 46, "fillB");
  txt(cmpG, 450, 90, "note", "Var(B) =", "start");
  txt(cmpG, 540, 94, "big", "12.5", "start").setAttribute("font-size", "22");

  var mlG = el("g", {}, svg);
  txt(mlG, 320, 40, "lbl", "standard deviation = √variance, in the original units", "middle");
  var SD = 40;
  card(mlG, 60, 70, 150, 56, "fillA");
  txt(mlG, 135, 104, "big", "Model A", "middle");
  box(mlG, 230, 82, 0.71 * SD * 2, 32, "rgba(56,189,248,0.85)", "none", 4);
  txt(mlG, 230 + 0.71 * SD * 2 + 8, 104, "lbl", "spread ≈ 0.71", "start");
  card(mlG, 60, 150, 150, 56, "fillB");
  txt(mlG, 135, 184, "big", "Model B", "middle");
  box(mlG, 230, 162, 3.54 * SD * 2, 32, "rgba(244,114,182,0.85)", "none", 4);
  txt(mlG, 230 + 3.54 * SD * 2 + 8, 184, "lbl", "≈ 3.54", "start");
  card(mlG, 60, 240, 520, 84, "fillG");
  txt(mlG, 320, 270, "lbl", "same average error, very different reliability", "middle");
  txt(mlG, 320, 300, "note", "larger variance = less predictable predictions, or a more spread-out feature", "middle");

  function render(index, id) {
    var i = index;
    show(gA, i <= 7 && i !== 7);
    show(gB, i <= 1 || i === 6);
    show(spreadG, i === 1);
    show(devA, i === 3 || i === 4);
    show(sqA, i === 4);
    show(devB, i === 6);
    show(sqB, i === 6);
    show(avgG, i === 5);
    show(cmpG, i === 6);
    show(mlG, i === 7);
    // In the final comparison, shift chart A upward area is the same; cards sit on the right.
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
